 func editDistance(a, b string) int {
 	previous := make([]int, len(b)+1)
 	for j := range previous {
 		previous[j] = j
 	}
 	for i := 1; i <= len(a); i++ {
 		current := make([]int, len(b)+1)
 		current[0] = i
 		for j := 1; j <= len(b); j++ {
 			cost := 0
 			if a[i-1] != b[j-1] {
 				cost = 1
 			}
 			current[j] = min(
 				current[j-1]+1,
 				previous[j]+1,
 				previous[j-1]+cost,
 			)
 		}
 		previous = current
 	}
 	return previous[len(b)]
 }

