  "required": ["kind"],
  "properties": {
    "kind": {
      "type": "string",
      "enum": ["pat", "github-app", "azure-cli", "workload-identity", "managed-identity"],
      "description": "Identity mechanism: `pat` reads the static token ref; `github-app` mints short-lived installation tokens (GitHub); `azure-cli` borrows the current local az login, `workload-identity` uses federated Azure workload identity, and `managed-identity` uses an Azure managed identity (all Azure DevOps). Every kind except `pat` forbids a token ref on the same repository."
    },
