{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://goobers.dev/schemas/gaggle.schema.json",
  "title": "Gaggle",
  "description": "A siloed workforce within an instance (GAG-001..007).",
  "type": "object",
  "additionalProperties": false,
  "required": ["apiVersion", "kind", "metadata", "spec"],
  "properties": {
    "apiVersion": { "const": "goobers.dev/v1alpha1", "description": "API version of this gaggle definition." },
    "kind": { "const": "Gaggle", "description": "Definition kind; always Gaggle." },
    "metadata": { "$ref": "#/$defs/metadata", "description": "Identity and optional labels or annotations for this gaggle." },
    "spec": {
      "type": "object",
      "description": "The gaggle's project, backlog, isolation boundary, and shared runner settings.",
      "additionalProperties": false,
      "required": ["project", "backlog", "isolation"],
      "properties": {
        "displayName": { "type": "string", "description": "Human-facing gaggle name shown in the portal." },
        "cost": {
          "type": "object",
          "description": "Overrides external cost publication without disabling local usage accounting.",
          "additionalProperties": false,
          "properties": {
            "enabled": {
              "type": ["boolean", "null"],
              "description": "Overrides instance cost.enabled when boolean; null or omitted inherits the instance default."
            }
          }
        },
        "selfIdentity": { "type": "string", "minLength": 1, "description": "Provider login used as this gaggle's self identity for assignment-aware backlog operations. Omitted inherits instance.yaml selfIdentity." },
        "project": { "$ref": "#/$defs/repoRef", "description": "Primary code repository this gaggle works on." },
        "backlog": { "$ref": "#/$defs/backlogRef", "description": "Singleton source of work-item truth for this gaggle." },
        "isolation": {
          "type": "object",
          "description": "Per-gaggle namespace and workload-identity boundary.",
          "additionalProperties": false,
          "required": ["namespace"],
          "properties": {
            "namespace": {
              "type": "string",
              "pattern": "^[a-z0-9]([-a-z0-9]*[a-z0-9])?$",
              "description": "Kubernetes namespace reserved for this gaggle's workloads and secrets."
            },
            "identityRef": { "type": "string", "description": "Per-gaggle Azure workload identity used for external services." }
          }
        },
        "additionalRepos": {
          "type": "array",
          "description": "Optional reference repositories supplied read-only to runs in addition to the primary project.",
          "items": { "$ref": "#/$defs/repoRef" }
        },
        "ciCommand": {
          "description": "Per-gaggle local CI-equivalent command run by the deterministic local-ci stage instead of its declared default (MGV-1/#1009).",
          "type": "array",
          "minItems": 1,
          "items": { "type": "string", "minLength": 1 }
        },
        "requiredCapabilities": {
          "description": "Runner (toolchain/platform) capabilities every run of this gaggle needs, matched at schedule time against a runner's advertised set (RRQ-1/#1101). DSL ≤2.0 only: DSL 3.0 removes this field in favor of spec.runsOn (dsl-3.0.md D1/D12); the 3.0 interpreter refuses it with a pointer diagnostic.",
          "type": "array",
          "items": { "$ref": "#/$defs/runnerCapability" }
        },
        "runsOn": {
          "description": "Gaggle-level placement floor (DSL 3.0 only, dsl-3.0.md §2): OS, toolchain capability tags, and required runner restrictions that merge into every stage of every workflow in this gaggle — capabilities and restrictions union with the stage's own; an OS conflict with a stage is a compile error. No quantities at gaggle level. Activates only for gaggles whose workflows pin DSL 3.0.",
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "os": {
              "description": "Operating system every stage of this gaggle requires — same validated enum as a stage's runsOn.os.",
              "type": "string",
              "enum": ["linux", "windows", "macOS"]
            },
            "capabilities": {
              "description": "Toolchain tags unioned into every stage's runsOn.capabilities (internal/runnercap grammar). os=* tokens are rejected (CAP004). maxItems bounds CRD CEL validation cost (#3168).",
              "type": "array",
              "maxItems": 32,
              "items": { "$ref": "#/$defs/runnerCapability" }
            },
            "restrictions": {
              "description": "Isolation effects unioned into every stage's runsOn.restrictions, from the closed v1 effect list (Goobernetes decision D7). Unknown tokens are rejected with a suggestion (CAP005). maxItems bounds CRD CEL validation cost (#3168).",
              "type": "array",
              "maxItems": 8,
              "items": {
                "type": "string",
                "enum": ["network:none", "network:allowlist", "fs:readonly-except-workspace", "tmp:ephemeral", "env:default-deny"]
              }
            }
          }
        },
        "branchNamespace": {
          "description": "refs/heads/ root this gaggle's run branches live under (providers.BranchName). Empty defaults to 'goobers/'. A trailing slash is optional. Must be a valid ref-path segment sequence (#965/#1010).",
          "type": "string",
          "pattern": "^([A-Za-z0-9][A-Za-z0-9._-]*/)*[A-Za-z0-9][A-Za-z0-9._-]*/?$"
        },
        "runControls": { "$ref": "#/$defs/runControls", "description": "Gaggle-level overrides for instance runner safety budgets." },
        "outboxMirrorPath": { "type": "string", "minLength": 1, "description": "Default absolute local filesystem root (or ~/ path) where workflows additionally mirror durable journal outbox files." },
        "sandbox": {
          "description": "Per-gaggle override of the instance-wide isolation posture for agentic stages (#1305). Omitted inherits the instance posture; the default is disabled (opt-in).",
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "agentic": { "type": "string", "enum": ["disabled", "enforced"], "description": "Isolation posture for agentic stages. Omitted inherits the instance posture." }
          }
        },
        "workcopies": {
          "description": "Per-gaggle override for managed working-copy placement. The gaggle name and repository key are appended beneath this base path.",
          "type": "object",
          "additionalProperties": false,
          "required": ["root"],
          "properties": {
            "root": { "type": "string", "minLength": 1, "description": "Absolute base path for this gaggle's managed mirrors and worktrees. Overrides instance.yaml workcopies.root." }
          }
        },
        "requireLabels": {
          "description": "Default requireLabels value every workflow's backlog-query task in this gaggle inherits unless the task declares its own requireLabels input (full replace, not merge — same shape as branchNamespace/headPrefix) (MIRC-2, #1901).",
          "type": "array",
          "items": { "type": "string", "minLength": 1 }
        },
        "siblings": {
          "description": "Other gaggles/instances known to independently work the same target repo, for the sibling-overlap validation warning (MIRC-2, #1901).",
          "type": "array",
          "items": { "$ref": "#/$defs/gaggleSibling" }
        }
      }
    }
  },
  "$defs": {
    "metadata": {
      "description": "Deliberately left open (no additionalProperties:false) unlike the rest of this schema: k8s-style metadata objects tolerate forward-compatible extra fields (e.g. a future resourceVersion) by convention (#125).",
      "type": "object",
      "required": ["name"],
      "properties": {
        "name": {
          "type": "string",
          "pattern": "^[a-z0-9]([-a-z0-9]*[a-z0-9])?$",
          "description": "DNS-label-compatible gaggle name, unique within the instance."
        },
        "labels": { "type": "object", "description": "String labels used to organize this gaggle.", "additionalProperties": { "type": "string" } },
        "annotations": { "type": "object", "description": "Non-identifying string metadata attached to this gaggle.", "additionalProperties": { "type": "string" } }
      }
    },
    "repoRef": {
      "type": "object",
      "description": "Provider-neutral reference to a git repository and its credential connection.",
      "additionalProperties": false,
      "required": ["provider", "owner", "name"],
      "properties": {
        "provider": { "type": "string", "enum": ["github", "ado", "gitea"], "description": "Repository provider." },
        "baseUrl": { "type": "string", "description": "Forge root URL (e.g. https://gitea.example.com); required when provider is gitea, since self-hosted Gitea has no fixed host." },
        "owner": { "type": "string", "minLength": 1, "description": "GitHub organization or user, or Azure DevOps organization." },
        "project": { "type": "string", "minLength": 1, "description": "Azure DevOps project. Omit for GitHub repositories." },
        "name": { "type": "string", "minLength": 1, "description": "Repository name." },
        "branch": { "type": "string", "description": "Default branch checked out by runs. Omitted defaults to main." },
        "connectionRef": { "type": "string", "description": "Manifest connection that supplies credentials for this repository." },
        "checkout": {
          "description": "Partial-checkout declaration (B2, #649). Accepted but not honored by the local runner yet — inert, surfaced as a VER003 compatibility warning at validate time.",
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "sparse": {
              "description": "Repo-relative path cones a sparse checkout materializes. Empty means a full checkout.",
              "type": "array",
              "items": { "type": "string", "minLength": 1 }
            }
          }
        }
      }
    },
    "gaggleSibling": {
      "type": "object",
      "description": "Another gaggle/instance known to independently work the same target repo — identified by target repo, never by gaggle name (MIRC-2, #1901).",
      "additionalProperties": false,
      "required": ["project"],
      "properties": {
        "project": { "$ref": "#/$defs/repoRef", "description": "Repo the sibling gaggle targets — the sole match key (provider/owner/name)." },
        "label": { "type": "string", "description": "Human-readable name for the sibling, used only in warning messages." },
        "requireLabels": {
          "description": "This gaggle's own trusted declaration of the sibling's effective required-label scope.",
          "type": "array",
          "items": { "type": "string", "minLength": 1 }
        }
      }
    },
    "runnerCapability": {
      "description": "A free-form, version-parameterized runner capability token (e.g. dotnet@8, xcode, os=windows) — distinct from a credential capability. An alphanumeric start then letters, digits, and any of . _ - + @ =, no whitespace.",
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._@=+-]*$"
    },
    "runControls": {
      "description": "Runner-level safety budgets inherited by this gaggle's workflows. Omitted fields retain instance defaults.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "maxRepasses": { "type": "integer", "minimum": 1, "description": "Maximum number of times gates may cumulatively route a run back to the same already-completed stage before escalation, regardless of gate or outcome." },
        "stalledRunTimeout": { "type": "string", "minLength": 1, "description": "Maximum journal-silent period before watchdog escalation, expressed as a Go duration." },
        "maxRunDuration": { "type": "string", "minLength": 1, "description": "Maximum total wall-clock age of a run, expressed as a Go duration. Omit to disable." }
      }
    },
    "backlogRef": {
      "type": "object",
      "description": "Provider-neutral reference to the singleton backlog a gaggle draws work from.",
      "additionalProperties": false,
      "required": ["provider", "project"],
      "properties": {
        "provider": { "type": "string", "enum": ["github", "ado", "gitea"], "description": "Backlog provider." },
        "baseUrl": { "type": "string", "description": "Forge root URL (e.g. https://gitea.example.com); required when provider is gitea, since self-hosted Gitea has no fixed host." },
        "project": { "type": "string", "minLength": 1, "description": "GitHub owner/repository or Azure DevOps project that scopes the backlog." },
        "labels": { "type": "array", "description": "Required labels used to narrow candidate work items.", "items": { "type": "string" } },
        "labelPredicate": {
          "type": "string",
          "minLength": 1,
          "description": "CEL label-set predicate using only string membership in `labels` and boolean &&, ||, and !. ANDed with labels."
        },
        "fieldPredicate": {
          "type": "string",
          "minLength": 1,
          "description": "CEL predicate over the provider's typed native-field projection. ANDed with labels; unavailable fields are errors."
        },
        "connectionRef": { "type": "string", "description": "Manifest connection that supplies credentials for this backlog." }
      }
    }
  }
}

