             "maxRunsPerHour": { "type": "integer", "minimum": 0, "description": "Rolling hourly run budget. An operator may explicitly bypass the ceiling for one manual invocation with `goobers run --force`. Zero or omitted both fall back to the scheduler default of 10 — NOT unlimited (that is instance.yaml's runConditions.maxParallelRuns, where zero does mean unlimited). Set an explicit large value if you want a high hourly ceiling." },
             "maxRunsPerDay": { "type": "integer", "minimum": 0, "description": "Rolling 24-hour run budget. An operator may explicitly bypass the ceiling for one manual invocation with `goobers run --force`. Zero or omitted disables the daily cap." },
             "maxChainDepth": { "type": "integer", "minimum": 0, "description": "Reserved maximum depth for signal-triggered workflow chains. The scheduler does not currently enforce this field, and configuring it has no effect." },
             "maxOpenPRs": { "type": "integer", "minimum": 0, "description": "Maximum open pull requests produced by this workflow. Zero or omitted disables the cap." }
           }
         },
         "runControls": { "$ref": "#/$defs/runControls", "description": "Workflow-level overrides for inherited runner safety budgets." },
         "outboxMirrorPath": { "type": "string", "minLength": 1, "description": "Absolute local filesystem root (or ~/ path) where durable journal outbox files are additionally mirrored. Tasks may override it." },
         "start": { "type": "string", "minLength": 1, "examples": ["act"], "description": "Name of the first task, gate, or parallel state." },
         "docsRoots": {
           "type": "array",
           "description": "In-repo documentation roots this workflow keeps current (docs-updater, #472/#1016). Ordered repo-relative paths (files or directories); the run's writes are confined to these roots. Each must be non-empty and must not escape the repository.",
           "items": { "type": "string", "minLength": 1 }
         },
         "tutorScope": {
           "type": "object",
           "description": "Declares this workflow as a Tutor-role definition and its topology tier (TUT-A4): per-workflow (confined to target's own subtree) or per-gaggle (the gaggle's shared config).",
           "additionalProperties": false,
           "required": ["tier"],
           "properties": {
             "tier": { "type": "string", "enum": ["per-workflow", "per-gaggle"], "description": "Tutor topology tier: confined to one workflow or shared across its gaggle." },
             "target": { "type": "string", "minLength": 1, "description": "Workflow name a per-workflow tutor is confined to. Omit for a per-gaggle tutor." }
           }
         },
         "requires": {
           "type": "object",
           "description": "Provider-capability requirements this workflow needs from its gaggle's connected provider (CONF-6, #2079). Distinct from a task's requiredCapabilities (runner/toolchain) and capabilities (credential grants). Omit to derive the requirement set from the stages this workflow uses; an explicit value here replaces that derivation entirely.",
           "additionalProperties": false,
           "properties": {
             "capabilities": {
               "type": "array",
               "description": "Provider capability keys this workflow requires (e.g. \"pr.merge\", \"pr.landing.enqueue\") — see docs/design/provider-contract-conformance.md §3.1.",
               "items": { "type": "string", "minLength": 1 }
             }
           }
         },
         "tasks": { "type": "array", "description": "Work states in the workflow state machine.", "items": { "$ref": "#/$defs/task" } },
         "gates": { "type": "array", "description": "Validation and branching states in the workflow state machine.", "items": { "$ref": "#/$defs/gate" } },
         "parallels": { "type": "array", "description": "Static fan-out/fan-in states in the workflow state machine.", "items": { "$ref": "#/$defs/parallel" } }
       }
     }
   },
   "$defs": {
     "branch": {
       "type": "object",
       "additionalProperties": false,
       "required": ["name", "start"],
       "properties": {
         "name": { "type": "string", "minLength": 1, "description": "Branch identifier used in journal events, completeness records, and branch-qualified input references." },
         "start": { "type": "string", "minLength": 1, "description": "Name of this branch's first task or gate." }
       }
     },
     "parallel": {
       "description": "A fan-out/fan-in state: forks the run into a statically-declared set of named branches and joins them at a single successor once every branch has settled. failurePolicy is required — there is no default. onFailure is required for fail_fast/all_or_nothing and forbidden under continue_on_error, where the join always runs and owns the decision.",
       "type": "object",
       "additionalProperties": false,
       "required": ["name", "failurePolicy", "branches", "join"],
       "properties": {
         "name": { "type": "string", "minLength": 1, "description": "State name used as a transition target." },
         "failurePolicy": { "type": "string", "enum": ["fail_fast", "all_or_nothing", "continue_on_error"], "description": "How branch failures affect sibling branches, the join state, and failure routing." },
         "branches": { "type": "array", "minItems": 2, "description": "Statically declared branches, assigned deterministic branch IDs in declaration order.", "items": { "$ref": "#/$defs/branch" } },
         "join": { "type": "string", "minLength": 1, "description": "State run once after all branches settle when the failure policy permits joining." },
         "onFailure": { "type": "string", "minLength": 1, "description": "State or reserved terminal target used when fail_fast or all_or_nothing observes a branch failure." },
         "branchTimeoutSeconds": { "type": "integer", "minimum": 0, "description": "Declared branch budget used only for compile-time task-timeout coherence checks. The runner does not currently enforce a branch wall-clock timeout." },
         "maxConcurrentBranches": { "type": "integer", "minimum": 1, "description": "Maximum number of branches dispatched concurrently. Omit or set to 1 for deterministic sequential execution. Values greater than 1 are supported only when every reachable branch stage uses a scratch or repo-readonly workspace; writable branch workspaces are rejected." }
       },
       "allOf": [
         {
           "if": { "properties": { "failurePolicy": { "const": "continue_on_error" } }, "required": ["failurePolicy"] },
           "then": { "not": { "required": ["onFailure"] } },
           "else": { "required": ["onFailure"] }
         }
       ]
     },
     "metadata": {
       "description": "Deliberately left open (no additionalProperties:false) unlike the rest of this schema: k8s-style metadata objects tolerate forward-compatible extra fields (e.g. a future resourceVersion) by convention (#125).",
       "type": "object",
       "required": ["name"],
       "properties": {
         "name": { "type": "string", "pattern": "^[a-z0-9]([-a-z0-9]*[a-z0-9])?$", "examples": ["offline-workflow"], "description": "DNS-label-compatible workflow name, unique within its gaggle." },
         "labels": { "type": "object", "description": "String labels used to organize this workflow.", "additionalProperties": { "type": "string" } },
         "annotations": { "type": "object", "description": "Non-identifying string metadata attached to this workflow.", "additionalProperties": { "type": "string" } }
       }
     },
     "runControls": {
       "description": "Runner-level safety budgets. Omitted fields inherit from gaggle then instance defaults.",
       "type": "object",
       "additionalProperties": false,
       "properties": {
         "maxRepasses": { "type": "integer", "minimum": 1, "description": "Maximum number of times gates may cumulatively route a run back to the same already-completed stage before escalation, regardless of gate or outcome." },
         "stalledRunTimeout": { "type": "string", "minLength": 1, "description": "Maximum journal-silent period before watchdog escalation, expressed as a Go duration." },
         "maxRunDuration": { "type": "string", "minLength": 1, "description": "Maximum total wall-clock age of a run, expressed as a Go duration. Omit to disable." }
       }
     },
     "trigger": {
       "type": "object",
       "additionalProperties": false,
       "required": ["type"],
       "properties": {
         "type": {
           "type": "string",
           "enum": ["manual", "backlog-item", "schedule", "signal", "webhook"],
           "description": "Trigger kind. backlog-item fans out scheduler runs from the provider's eligible-item count; webhook requires GitHub event names in events."
         },
         "selector": {
           "type": "object",
           "description": "For backlog-item triggers, selector keys are required labels and values are ignored.",
           "additionalProperties": { "type": "string" }
         },
         "trustLabel": {
           "type": "string",
           "minLength": 1,
           "description": "Explicit SEC-047 approval label used to classify a directly triggered backlog item as maintainer integrity. Selector labels remain routing criteria and never imply approval."
         },
         "labelPredicate": {
           "type": "string",
           "minLength": 1,
           "description": "CEL label-set predicate using only string membership in `labels` and boolean &&, ||, and !. ANDed with selector."
         },
         "fieldPredicate": {
           "type": "string",
           "minLength": 1,
           "description": "CEL predicate over the provider's typed native-field projection. ANDed with selector; unavailable fields are errors."
         },
         "priority": {
           "type": "integer",
           "description": "Provider polling priority. Higher values are preserved first when a quota window cannot cover every due poll."
         },
         "schedule": { "type": "string", "description": "Cron expression or @every interval used by a schedule trigger." },
         "idleBackoff": {
           "type": "object",
           "description": "Adaptive delay after consecutive scheduled runs find no work. Omitted defaults to enabled with a one-minute floor and fifteen-minute ceiling.",
           "additionalProperties": false,
           "properties": {
             "enabled": { "type": "boolean", "description": "Enable adaptive idle backoff. Defaults to true." },
             "floor": { "type": "string", "minLength": 1, "description": "Minimum idle interval as a positive Go duration. Defaults to 1m." },
             "ceiling": { "type": "string", "minLength": 1, "description": "Maximum idle interval as a positive Go duration. Defaults to 15m and must not be below floor." }
           }
         },
         "signal": { "type": "string", "description": "External signal name used by a signal trigger." },
         "events": {
           "type": "array",
           "description": "GitHub webhook event names accepted by a webhook trigger, such as pull_request, issues, or check_suite.",
           "minItems": 1,
           "items": { "type": "string", "minLength": 1 }
         },
         "enabled": {
           "type": "boolean",
           "description": "Toggle whether the scheduler honors this trigger without removing it. Omit to preserve the historical enabled behavior; false disables schedule, signal, webhook, and backlog-item triggers. type=manual is always allowed because manual runs are started from the operator surface."
         }
       },
       "allOf": [
         {
           "if": { "required": ["trustLabel"] },
           "then": {
             "properties": { "type": { "const": "backlog-item" } }
           }
         },
         {
           "if": { "required": ["idleBackoff"] },
           "then": {
             "properties": { "type": { "const": "schedule" } }
           }
         }
       ]
     },
     "task": {
       "type": "object",
       "additionalProperties": false,
       "required": ["name", "type", "goal"],
       "properties": {
         "name": { "type": "string", "minLength": 1, "examples": ["act"], "description": "State name, unique within this workflow." },
         "type": { "type": "string", "enum": ["deterministic", "agentic"], "description": "Execution kind: deterministic runs declared code; agentic invokes a goober." },
         "goal": { "type": "string", "minLength": 1, "examples": ["Run the offline-authored step."], "description": "Intended outcome supplied to the stage invocation." },
         "goober": { "type": "string", "description": "Goober definition invoked by an agentic task. Forbidden for deterministic tasks." },
         "run": {
           "type": "object",
           "description": "Host command or script executed by a deterministic task. Forbidden for agentic tasks.",
           "additionalProperties": false,
           "properties": {
             "command": { "type": "array", "minItems": 1, "examples": [["sh", "-c", "true"]], "description": "Executable followed by its arguments, invoked without shell interpretation.", "prefixItems": [{ "type": "string", "minLength": 1, "pattern": "\\S", "description": "Executable name or path; must contain a non-whitespace character." }], "items": { "type": "string" } },
             "script": { "type": "string", "minLength": 1, "description": "Inline script executed by the host's native command interpreter. Mutually exclusive with command." },
             "env": { "type": "object", "description": "Explicit environment variables added to the runner's minimal environment and scoped credentials.", "additionalProperties": { "type": "string" } },
             "network": { "type": "string", "enum": ["none"], "description": "Network policy for the command. Set to none to deny network access." },
             "workspace": { "type": "string", "enum": ["repo", "scratch", "repo-readonly"], "description": "Workspace provisioned for the command: writable repository, empty scratch directory, or detached read-only repository." },
             "syncBase": { "type": "boolean", "description": "Whether to merge the freshly fetched base ref into an existing run branch before execution. Valid only for a writable repository workspace." },
             "injectRunContext": { "type": "boolean", "description": "Explicitly inject the run's operational identity (GOOBERS_RUN_ID, GOOBERS_GAGGLE, and related env) even though command[0] is not the goobers CLI. For a deterministic stage that wraps the goobers CLI in another process and needs the same context its nested invocation would receive." }
           },
           "oneOf": [
             { "required": ["command"] },
             { "required": ["script"] }
           ],
           "allOf": [
             {
               "not": {
                 "properties": {
                   "workspace": { "enum": ["scratch", "repo-readonly"] },
                   "syncBase": { "const": true }
                 },
                 "required": ["workspace", "syncBase"]
               }
             }
           ]
         },
         "workspace": { "type": "string", "enum": ["repo", "scratch", "repo-readonly"], "description": "Workspace provisioned for an agentic task. Deterministic tasks use run.workspace instead." },
         "outbox": {
           "type": "array",
           "description": "Workspace-relative paths (files or directories) this stage durably exports into the run journal's outbox namespace on completion, for output that isn't something that can PR against a repo. A declared path that is missing is skipped; one that escapes the workspace fails the stage closed.",
           "maxItems": 32,
           "items": { "type": "string", "minLength": 1 }
         },
         "outboxMirrorPath": { "type": "string", "minLength": 1, "description": "Task-level override for the local outbox mirror root. Most specific value wins over workflow and gaggle settings." },
         "inputs": { "type": "object", "description": "Static task-specific values merged into the invocation envelope's inputs.", "additionalProperties": { "type": "string" } },
         "inputsFrom": { "type": "object", "description": "Explicit input-key to preceding-output-key mappings for task-to-task scalar handoff.", "additionalProperties": { "type": "string" } },

