"runner": {
  "description": "What this runner advertises and how it bounds a stage. These are claims and defaults, not installation instructions: Goobers never installs a toolchain.",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "capabilities": {
      "description": "Toolchain and platform capabilities this runner claims are ALREADY INSTALLED. The scheduler admits a run only when this set contains every capability the run's gaggle (spec.requiredCapabilities) and stages (task requiredCapabilities) declare, so a gaggle requiring `dotnet@8` on a runner that does not claim it never schedules a single run — the run does not fail, it never starts. Empty claims nothing, which is correct only while no gaggle or stage requires anything. Matching is exact string membership, so `dotnet@8` and `dotnet@10` are distinct capabilities, never a range. A false claim is not caught here: it degrades to a runtime error in the stage that needs the toolchain.",
      "type": "array",
      "items": { "$ref": "#/$defs/runnerCapability" }
    },
    "envPassthrough": {
      "description": "Additional ambient environment variable NAMES carried from the daemon process into every deterministic stage and harness subprocess, on top of the built-in default-deny allowlist. That allowlist already covers PATH/HOME/TMPDIR, Windows profile and shell paths, locale and proxy variables, and the Go, .NET/NuGet, Python, Node, Rust, and Java/Maven/Gradle toolchain families — so this list is for a variable those families miss, such as a private NUGET_CONFIG_FILE or a bespoke FOO_HOME. It stays default-deny: an explicit opt-in list of names, never a value and never a whole-environment passthrough. A name whose variable is unset is a harmless no-op, and a name that would expose a configured secret ref to stages is refused at load.",
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^[A-Za-z_][A-Za-z0-9_]*(\\([A-Za-z0-9_]+\\))?$",
        "description": "A POSIX-shaped environment variable name, or one of the standard Windows \"x86\" twins such as ProgramFiles(x86)/CommonProgramFiles(x86) (#3753). Malformed names are rejected at load rather than mis-split at stage launch.",
        "examples": ["NUGET_CONFIG_FILE", "ProgramFiles(x86)"]
      }
    },
    "defaultStageTimeout": {
      "description": "Baseline deadline for a deterministic stage that declares no timeoutSeconds of its own, as a Go duration. Unset keeps the built-in 10 minutes, which is sized for short commands rather than a mature repository's build+test entrypoint: if `make ci` routinely runs 15 minutes, raise this once here instead of stamping timeoutSeconds onto every such stage in every workflow. A stage's own timeoutSeconds always wins; this only moves the floor. Sizing it too low is not free — a timed-out stage is reported retryable, so a workflow that routes the failure to an agent spends a repass on something no diff can fix.",
      "$ref": "#/$defs/duration",
      "examples": ["25m"]
    },
    "stageMemoryLimit": {
      "description": "Memory ONE stage subprocess may use, as a Kubernetes quantity. Stage subprocesses share the daemon's own memory cgroup, so without a bound a single heavy stage can get the control-plane daemon OOM-killed and take every in-flight run with it (#4070); the admission-side memory gate cannot prevent this, because it refuses to START runs while the cgroup is hot and the killing allocation is a stage already running. There is deliberately NO default: the obvious one (pod limit less a daemon reserve) does not survive the recorded incidents, where children of 5.07 and 7.4 GiB killed a 10Gi pod in company with page cache, the daemon, and concurrent sibling stages. Unset, stages run unbounded and the daemon says so at every start. Enforced through a child cgroup where the memory controller is delegated to child cgroups, otherwise through RLIMIT_AS — which bounds ADDRESS SPACE rather than resident memory, so verify a value against a real stage. A breach fails the stage with stage_memory_exceeded rather than killing the daemon.",
      "type": "string",
      "examples": ["8Gi", "4Gi"]
    },
    "livenessTimeout": {
      "description": "Maximum age of the scheduler tick heartbeat before the daemon reports itself unhealthy. Empty defaults to 2 minutes; values below 2 seconds are rejected.",
      "$ref": "#/$defs/duration",
      "examples": ["2m"]
    },
    "harnessCommand": {
      "description": "Overrides the base CLI invocation (argv[0..]) launched for a harness, keyed by harness name. Unset keys keep the built-in default. This is the adopter escape hatch for running the same engine CLI through a wrapper — the wrapper name lives only in this file, never in the harness enum. It replaces the launch prefix only, so it is safe solely for a launcher that honors the same CLI contract (session capture, completion-file readback) as the harness it overrides.",
      "type": "object",
      "additionalProperties": {
        "description": "Full argv for the harness launcher. The first element is the program and must be non-empty.",
        "type": "array",
        "minItems": 1,
        "items": { "type": "string", "minLength": 1 }
      },
      "propertyNames": { "$ref": "#/$defs/harnessName" }
    }
  }
},

